<?php
declare(strict_types=1);namespace Pam\Native\DevTools;final readonly class Redactor{public function __construct(private array$keys=['authorization','cookie','set-cookie','password','token','secret','api_key']){}public function redact(mixed$value,int$depth=0):mixed{if($depth>8)return'[max-depth]';if(is_array($value)){if(count($value)>256)$value=array_slice($value,0,256,true);$out=[];foreach($value as$k=>$v)$out[$k]=is_string($k)&&in_array(strtolower($k),$this->keys,true)?'[redacted]':$this->redact($v,$depth+1);return$out;}if(is_object($value))return['class'=>$value::class,'properties'=>$this->redact(get_object_vars($value),$depth+1)];if(is_resource($value))return'[resource]';if(is_string($value))return mb_substr($value,0,4096);if(is_scalar($value)||$value===null)return$value;return'[unsupported]';}}
